def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.162.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.161.0"' not in init:
        sys.exit("ABORT: not at v3.161.0.")
    for k in ("chart_gl", "journal_entries"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("ACC1", LESSONS_A1, QUESTIONS_A1, 9) + _validate("ACC2", LESSONS_A2, QUESTIONS_A2, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("ACC 1", LESSONS_A1, QUESTIONS_A1, "chart_gl",
         "The Accounting workspace foundation: GL Entries and the View > Accounting Ledger button, reading the debit/credit columns, building the Chart of Accounts tree with Add Child and the reading test, the Account Type field and the Company record's default accounts, the posting map document by document with the Stock Received But Not Billed diagnostic, the General Ledger and Trial Balance reports with the monthly scan, and the Receivable/Payable party ledgers with the tie check."),
        ("ACC 2", LESSONS_A2, QUESTIONS_A2, "journal_entries",
         "The Journal Entry doctype: what it bypasses, the form field by field (Entry Type, the Accounting Entries table, the Difference field, References, User Remark), the lawful list with the document and evidence tests, prepayments by Auto Repeat and accruals by Reverse Journal Entry, the four correction rules with Cancel/Amend and the note machinery, the forbidden list with the system's own fences, and the controls — Role Permissions, Workflow thresholds, templates, the five-question monthly review."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.161.0"', '"3.162.0"'))
    print("  data: ACCOUNTS 1 + 2 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.162.0")


if __name__ == "__main__":
    main()
